import itertools
import json
import unicodedata

def norm(s):
    return unicodedata.normalize("NFD", s.replace("’", "'"))

givens = [
    ("tmi'gn", "dəmīgən"),
    ("an'stawteg", "anəstawtek"),
    ("gjiansale'wit", "əkciansalēwit"),
    ("mgumie'jo'tlatl", "əmkumiējōdəladəl"),
    ("amqwanji'j", "amxʷancīc"),
    ("e'jnt", "ējənt"),
    ("tplutaqan", "ətpəludaɣan"),
    ("ge'gwising", "gēgʷisink"),
    ("lnu'sgw", "lənūskw"),
    ("g'p'ta'q", "gəbədāx"),
    ("epsaqtejg", "epsaxteck"),
]
vowels = set("aeiouə")
sonorants = set("lmn")
stops = {"t": ("t", "d"), "p": ("p", "b"),
         "g": ("k", "g"), "q": ("x", "ɣ"), "j": ("c", "j")}

def is_vowel(token):
    return token[0] in vowels

def transcribe(word):
    tokens = []
    for char in norm(word):
        if char == "'":
            if tokens and is_vowel(tokens[-1]) and tokens[-1] != "ə":
                tokens[-1] += "\u0304"
            else:
                tokens.append("ə")
        else:
            tokens.append(char)

    out = []
    if (len(tokens) > 1 and not is_vowel(tokens[0])
            and not is_vowel(tokens[1])
            and tokens[1] not in sonorants):
        out.append("ə")

    i = 0
    while i < len(tokens):
        token = tokens[i]
        previous = tokens[i - 1] if i else None
        following = tokens[i + 1] if i + 1 < len(tokens) else None

        if token in stops:
            voiced = (
                following is not None
                and (
                    (previous is not None and is_vowel(previous))
                    or (i == 0 and
                        (is_vowel(following) or following in sonorants))
                )
            )
            sound = stops[token][int(voiced)]
        else:
            sound = token

        # A medial w after g or q is realized as labialization.
        if (token in ("g", "q") and following == "w"
                and i + 2 < len(tokens) and is_vowel(tokens[i + 2])):
            sound += "ʷ"
            out.append(sound)
            i += 2
            continue

        out.append(sound)
        if (not is_vowel(token) and following in sonorants):
            out.append("ə")
        i += 1

    return norm("".join(out))

checks = [transcribe(w) == norm(p) for w, p in givens]
if not all(checks):
    print(json.dumps({"final_answer": "UNSUPPORTED",
                      "evidence": {"matched_examples": sum(checks)}}))
else:
    target = norm("alaptək")

    # Enumerate inverse spellings. Schwa may be explicitly written
    # with an apostrophe or supplied by consonant-cluster repair.
    inverse = {
        "ə": ["", "'"],
        "k": ["g"],
        "t": ["t"],
        "p": ["p"],
        "a": ["a"],
        "l": ["l"],
    }
    candidates = {
        "".join(parts)
        for parts in itertools.product(*(inverse[c] for c in target))
    }
    solutions = sorted(w for w in candidates if transcribe(w) == target)

    answer = solutions[0].replace("'", "’") if len(solutions) == 1 else "UNSUPPORTED"
    print(json.dumps({
        "final_answer": answer,
        "evidence": {
            "matched_examples": sum(checks),
            "enumerated": {
                w.replace("'", "’"): transcribe(w)
                for w in sorted(candidates)
            },
            "unique_match": len(solutions) == 1
        }
    }, ensure_ascii=False))
