import json
from fractions import Fraction as F

# Write t = exp(s), x = tau*X(t), y = tau*Y(t), u = tau^2*U(t).
# Laurent polynomials are represented by {power of t: coefficient}.
def poly(terms):
    return {k: F(v) for k, v in terms.items() if v != 0}

def ds(a):
    return poly({k: k * v for k, v in a.items()})

def scale(a, c):
    return poly({k: c * v for k, v in a.items()})

def at_initial(a):
    return sum(a.values(), F(0))

options = [
    (poly({1: 3, 0: -3}),
     poly({-1: F(1, 2), 0: F(1, 2)}),
     poly({-2: 1})),
    (poly({1: 2, 0: -2}),
     poly({2: 2, 0: -1}),
     poly({0: F(1, 2), -2: F(1, 2)})),
    (poly({1: 2, 0: -2}),
     poly({1: F(1, 2), 0: F(1, 2)}),
     poly({2: 1})),
    (poly({-1: 1, 0: -1}),
     poly({-1: -2, 0: 3}),
     poly({-2: 2, 0: -1})),
]

# For F = pq-u, Charpit gives:
# x'=q, y'=p, u'=2pq=2u, p'=p, q'=q.
# Along the initial curve, q=du/dtau=2*tau.
# Thus pq=tau^2 implies p=tau/2 for tau != 0,
# with the same value at zero by continuity.
q0_scaled = F(2)
p0_scaled = F(1) / q0_scaled
expected_dx = poly({1: q0_scaled})
expected_dy = poly({1: p0_scaled})

checks = []
matches = []
for index, (x, y, u) in enumerate(options, 1):
    initial_ok = (
        at_initial(x) == 0
        and at_initial(y) == 1
        and at_initial(u) == 1
    )
    charpit_ok = (
        ds(x) == expected_dx
        and ds(y) == expected_dy
        and ds(u) == scale(u, F(2))
    )
    checks.append({
        "option": index,
        "initial_curve": initial_ok,
        "charpit_equations": charpit_ok,
    })
    if initial_ok and charpit_ok:
        matches.append(index)

def format_poly(a):
    return {str(k): str(v) for k, v in sorted(a.items())}

evidence = {
    "charpit": ["x'=q", "y'=p", "u'=2u", "p'=p", "q'=q"],
    "initial": {
        "p/tau": str(p0_scaled),
        "q/tau": str(q0_scaled),
        "tau_zero": "continuous family gives x=y=u=p=q=0",
    },
    "checks": checks,
}
if len(matches) == 1:
    chosen = matches[0]
    x, y, u = options[chosen - 1]
    evidence["curves_as_laurent_coefficients_in_exp_s"] = {
        "x/tau": format_poly(x),
        "y/tau": format_poly(y),
        "u/tau^2": format_poly(u),
    }
    answer = str(chosen)
else:
    answer = "UNSUPPORTED"

print(json.dumps({"final_answer": answer, "evidence": evidence},
                 separators=(",", ":")))
