from fractions import Fraction as Q

# Laurent polynomials in z = exp(s), with exact rational coefficients.
# x,y are normalized by tau and u by tau^2. Thus polynomial identities
# establish the result for every tau, not merely sampled values of s.
def poly(*terms):
    return {k: Q(v) for k, v in terms if v}

def add(a, b):
    c = a.copy()
    for k, v in b.items():
        c[k] = c.get(k, Q(0)) + v
    return {k: v for k, v in c.items() if v}

def scale(a, c):
    return {k: v * c for k, v in a.items() if v * c}

def sub(a, b):
    return add(a, scale(b, -1))

def mul(a, b):
    c = {}
    for i, v in a.items():
        for j, w in b.items():
            c[i + j] = c.get(i + j, Q(0)) + v * w
    return {k: v for k, v in c.items() if v}

def derivative(a):
    # d/ds z^k = k*z^k
    return {k: k * v for k, v in a.items() if k * v}

def at_zero(a):
    # s=0 means z=1.
    return sum(a.values(), Q(0))

def show(a):
    if not a:
        return "0"
    return " + ".join(f"({v})*exp({k}*s)" for k, v in sorted(a.items()))

options = {
    1: (poly((1, 3), (0, -3)),
        poly((-1, Q(1, 2)), (0, Q(1, 2))),
        poly((-2, 1))),
    2: (poly((1, 2), (0, -2)),
        poly((2, 2), (0, -1)),
        poly((0, Q(1, 2)), (-2, Q(1, 2)))),
    3: (poly((1, 2), (0, -2)),
        poly((1, Q(1, 2)), (0, Q(1, 2))),
        poly((2, 1))),
    4: (poly((-1, 1), (0, -1)),
        poly((-1, -2), (0, 3)),
        poly((-2, 2), (0, -1))),
}

# F=p*q-u gives Charpit equations:
# x'=q, y'=p, u'=2*p*q, p'=p, q'=q.
# Along the initial curve, q(0)=2*tau; for tau != 0,
# p(0)=tau/2 follows from p(0)*q(0)=tau^2.
valid = []
for number, (x, y, u) in options.items():
    p, q = derivative(y), derivative(x)
    residuals = {
        "PDE p*q-u (divided by tau^2)": sub(mul(p, q), u),
        "u'-2*p*q (divided by tau^2)":
            sub(derivative(u), scale(mul(p, q), 2)),
        "p'-p (divided by tau)": sub(derivative(p), p),
        "q'-q (divided by tau)": sub(derivative(q), q),
    }
    initial = (at_zero(x), at_zero(y), at_zero(u))
    initial_slopes = (at_zero(p), at_zero(q))
    ok = (
        initial == (Q(0), Q(1), Q(1))
        and initial_slopes == (Q(1, 2), Q(2))
        and all(not r for r in residuals.values())
    )
    if ok:
        valid.append(number)
    print(f"Option {number}: initial (x/tau,y/tau,u/tau^2) = {initial}")
    print(f"  Initial (p/tau,q/tau) = {initial_slopes}")
    for name, residual in residuals.items():
        print(f"  {name}: {show(residual)}")
    print("  Valid standard Charpit family:", ok)

print("Exact matching options:", valid)
print("Expected: option 3")
print("x=2*tau*(exp(s)-1), y=tau*(exp(s)+1)/2, u=tau^2*exp(2*s)")
print("Submitted option 1: at tau=1,s=0, p*q-u =",
      at_zero(sub(mul(derivative(options[1][1]),
                         derivative(options[1][0])), options[1][2])))
print("Boundary tau=0: option 3 is the stationary characteristic with p=q=0.")
print("At tau=0 alone, initial p is undetermined; the smooth family above "
      "selects p=0 by continuity from nonzero tau.")
print("CHECK FAIL" if valid == [3] else "CHECK UNKNOWN")
