import math
import json

# Coordinates are rounded in the question; geometric comparisons allow for
# that rounding. All closed walks are enumerated, rather than inferred visually.
raw = """
24.38698,-19.9365 29.3405,-17.62663
0,7 0,5.46
10.35209,0 10.35209,-7.0986
