34.99586,-14.98949 24.85302,6.76189
15.16487,-17.41963 10.35209,-7.0986
11.74658,15.93912 11.17484,9.40408
0,0 4.03732,0
11.17484,9.40408 10.79637,5.0782
29.3405,-17.62663 34.99586,-14.98949
10.35209,0 10.35209,1.96
10.79637,5.0782 10.35209,0
7.55703,7 0,7
17.25429,-14.80182 18.29129,-17.02568
"""

EPS = 0.00005
def sub(a, b):
    return (a[0]-b[0], a[1]-b[1])
def cross(a, b):
    return a[0]*b[1]-a[1]*b[0]
def dot(a, b):
    return a[0]*b[0]+a[1]*b[1]
def norm(a):
    return math.hypot(*a)
def near(a, b):
    return norm(sub(a, b)) <= EPS
def parallel(a, b):
    return abs(cross(a, b)) <= 0.00002*norm(a)*norm(b)
def perpendicular(a, b):
    return abs(dot(a, b)) <= 0.00002*norm(a)*norm(b)

segments = []
for line in raw.strip().splitlines():
    p = [tuple(map(float, s.split(","))) for s in line.split()]
    segments.extend(zip(p, p[1:]))

points = []
def vertex(p):
    for i, q in enumerate(points):
        if near(p, q):
            return i
    points.append(p)
    return len(points)-1

cuts = []
for a, b in segments:
    cuts.append({vertex(a), vertex(b)})

# Split at every segment intersection and every endpoint on another segment.
for i, (a, b) in enumerate(segments):
    r = sub(b, a)
    for j in range(i+1, len(segments)):
        c, d = segments[j]
        s = sub(d, c)
        den = cross(r, s)
        if abs(den) > 1e-12:
            t = cross(sub(c, a), s)/den
            u = cross(sub(c, a), r)/den
            if -EPS/norm(r) <= t <= 1+EPS/norm(r) and \
               -EPS/norm(s) <= u <= 1+EPS/norm(s):
                p = (a[0]+t*r[0], a[1]+t*r[1])
                v = vertex(p)
                cuts[i].add(v)
                cuts[j].add(v)
        for p, source, target, x, y in (
            (a, i, j, c, d), (b, i, j, c, d),
            (c, j, i, a, b), (d, j, i, a, b)
        ):
            vxy = sub(y, x)
            t = dot(sub(p, x), vxy)/dot(vxy, vxy)
            if -EPS/norm(vxy) <= t <= 1+EPS/norm(vxy):
                projection = (x[0]+t*vxy[0], x[1]+t*vxy[1])
                if near(p, projection):
                    cuts[target].add(vertex(p))

adj = [set() for _ in points]
for (a, b), cut in zip(segments, cuts):
    direction = sub(b, a)
    ordered = sorted(cut, key=lambda v: dot(sub(points[v], a), direction))
    for u, v in zip(ordered, ordered[1:]):
        if u != v:
            adj[u].add(v)
            adj[v].add(u)

cycles = []
for start in range(len(points)):
    def walk(path, used):
        for v in sorted(adj[path[-1]]):
            if v == start:
                if len(path) >= 3 and path[1] < path[-1]:
                    cycles.append(path[:])
            elif v > start and v not in used:
                walk(path+[v], used | {v})
    walk([start], {start})

def corners(cycle):
    p = [points[v] for v in cycle]
    changed = True
    while changed and len(p) > 2:
        changed = False
        for i in range(len(p)):
            a = sub(p[i], p[i-1])
            b = sub(p[(i+1) % len(p)], p[i])
            if parallel(a, b) and dot(a, b) > 0:
                p.pop(i)
                changed = True
                break
    return p

def drawn(a, b):
    v = sub(b, a)
    length = norm(v)
    intervals = []
    for c, d in segments:
        if abs(cross(sub(c, a), v))/length <= EPS and \
           abs(cross(sub(d, a), v))/length <= EPS:
            x, y = sorted((dot(sub(c, a), v)/dot(v, v),
                           dot(sub(d, a), v)/dot(v, v)))
            if y >= 0 and x <= 1:
                intervals.append((max(0, x), min(1, y)))
    end = 0.0
    for x, y in sorted(intervals):
        if x > end + EPS/length:
            return False
        end = max(end, y)
    return end >= 1-EPS/length

def has_diagonal(p):
    n = len(p)
    return any(drawn(p[i], p[j])
               for i in range(n) for j in range(i+1, n)
               if j != i+1 and not (i == 0 and j == n-1))

found = {}
for cycle in cycles:
    p = corners(cycle)
    n = len(p)
    if n < 3:
        continue
    edges = [sub(p[(i+1) % n], p[i]) for i in range(n)]
    turns = [cross(edges[i], edges[(i+1) % n]) for i in range(n)]
    convex = all(x > 0 for x in turns) or all(x < 0 for x in turns)
    right = [perpendicular(edges[i-1], edges[i]) for i in range(n)]
    lengths = [norm(e) for e in edges]
    equal_sides = max(lengths)-min(lengths) <= EPS*4
    cosines = [dot(edges[i-1], edges[i]) /
               (lengths[i-1]*lengths[i]) for i in range(n)]
    regular = convex and equal_sides and max(cosines)-min(cosines) < 0.00005
    kinds = []
    if n == 3:
        kinds = [4 if any(right) else 3]
    elif not has_diagonal(p):
        if n == 4:
            pairs = sum((parallel(edges[0], edges[2]),
                         parallel(edges[1], edges[3])))
            if all(right):
                kinds = [2 if equal_sides else 1]
            elif pairs == 2:
                kinds = [5]
            elif convex and pairs == 1:
                kinds = [6]
        elif n == 5:
            kinds = [9 if regular else (7 if convex else 8)]
        elif n == 6 and regular:
            kinds = [10]
    for kind in kinds:
        found.setdefault(kind, [[round(x, 5), round(y, 5)] for x, y in p])

options = {
    "A": {1,7,3}, "B": {1,8}, "C": {7,9}, "D": {5},
    "E": {1,5,7,8}, "F": {1,5,7,8,4,6}, "G": {7,8,2,10},
    "H": {1,8,9}, "I": {5,3}, "J": {1}, "K": {7,8},
    "L": {5,8}, "M": {5,2}, "N": {1,8,2,4,9},
    "O": {1,5,7,8,10}, "P": {1,7,8,6}
}
matches = [key for key, value in options.items() if value == set(found)]
answer = matches[0] if len(matches) == 1 else "UNSUPPORTED"
print(json.dumps({
    "final_answer": answer,
    "evidence": {
        "shape_numbers": sorted(found),
        "witness_vertices": found,
        "simple_cycles_examined": len(cycles)
    }
}, separators=(",", ":")))
