from itertools import permutations

# Standard adjective classes; their order is inferred from the examples,
# not assumed from ordinary English.
classes = ("opinion", "size", "age", "shape",
           "color", "origin", "material", "purpose")

# These supplied examples witness every distinct inter-class precedence
# relation in the question. Single-adjective examples add no relations.
witnesses = [
    (4, ("material", "age")),                  # paper ancient
    (11, ("origin", "shape")),                 # bangladeshi spherical
    (17, ("color", "opinion")),                # maroon good
    (19, ("size", "purpose")),                 # medium-size hiking
    (40, ("shape", "size", "age")),            # triangular large new
    (175, ("origin", "purpose", "material")),   # iranian eating glass
]
edges = set()
for _, sequence in witnesses:
    for i in range(len(sequence)):
        for j in range(i + 1, len(sequence)):
            edges.add((sequence[i], sequence[j]))

vocabulary = {
    "opinion": "repulsive silly ridiculous lovely terrible",
    "size": "massive midsize medium-size small enormous huge",
    "age": "brand-new ancient old old-fashioned new",
    "shape": "pyramidal rectangular circular prismlike triangular",
    "color": "green yellow indigo gray pink violet brown",
    "origin": "ethiopian turkish japanese bangladeshi",
    "material": "wool plastic glass cardboard paper steel leather wood",
    "purpose": "hiking typing driving whittling eating drinking",
}
category = {
    word: kind
    for kind, words in vocabulary.items()
    for word in words.split()
}

# Nouns are omitted because only adjective order is being tested.
options = {
    "A": "massive hiking wool old-fashioned green silly",
    "B": "repulsive midsize typing plastic brand-new pyramidal ethiopian",
    "C": "ethiopian rectangular medium-size driving glass ancient repulsive",
    "D": "turkish circular massive whittling cardboard old yellow lovely",
    "E": "japanese prismlike small eating paper old-fashioned indigo",
    "F": "massive typing paper old-fashioned ridiculous gray",
    "G": "pyramidal medium-size drinking steel new pink ridiculous",
    "H": "violet lovely enormous hiking leather new triangular",
    "I": "terrible brown normal-size typing glass old triangular japanese",
    "J": "bangladeshi prismlike huge drinking wood ancient",
}
category["normal-size"] = "size"
sequences = {
    letter: tuple(category[word] for word in phrase.split())
    for letter, phrase in options.items()
}

# Exhaustively enumerate every total class order consistent with the data.
orders = []
for order in permutations(classes):
    rank = {kind: i for i, kind in enumerate(order)}
    if all(rank[a] < rank[b] for a, b in edges):
        orders.append(rank)

assert orders, "The inferred constraints are inconsistent."

counts = {}
for letter, sequence in sequences.items():
    counts[letter] = sum(
        all(rank[sequence[i]] < rank[sequence[i + 1]]
            for i in range(len(sequence) - 1))
        for rank in orders
    )

possible = "".join(letter for letter in options if counts[letter])
forced = "".join(letter for letter in options
                 if counts[letter] == len(orders))

print("Consistent total class orders:", len(orders))
for letter in options:
    print(f"{letter}: valid in {counts[letter]}/{len(orders)} orders")
print("Compatible choices:", possible)
print("Choices guaranteed by the supplied constraints:", forced)

# K claims that no option is correct. A universally valid option refutes
# that claim even if the examples leave some other class relations open.
submitted = "K"
if submitted == "K" and forced:
    print("CHECK FAIL")
    print("Decisive counterexample: J is correct in every consistent order.")
elif submitted == "K" and not possible:
    print("CHECK PASS")
else:
    print("CHECK UNKNOWN")
    print("UNSUPPORTED: the remaining unconstrained orders affect the claim.")
