from fractions import Fraction as F

c = F(20, -24) - (F(2) + F(-3))

# Polynomials are stored as {power: coefficient}.
original = {4: F(1, 16), 3: -c, 2: F(1, 8), 1: F(0), 0: F(1)}
derivative = {
    power - 1: power * coefficient
    for power, coefficient in original.items()
    if power > 0 and coefficient != 0
}
submitted = {3: F(1, 4), 2: F(57, 24), 1: F(1, 4)}

def multiply(a, b):
    result = {}
    for i, ai in a.items():
        for j, bj in b.items():
            result[i + j] = result.get(i + j, F(0)) + ai * bj
    return {i: ai for i, ai in result.items() if ai != 0}

def evaluate(poly, value):
    return sum((coefficient * value**power
                for power, coefficient in poly.items()), F(0))

# Expand (1/4)*s*(s-1)^2 to verify the factorization exactly.
factored_expansion = multiply(
    multiply({1: F(1, 4)}, {1: F(1), 0: F(-1)}),
    {1: F(1), 0: F(-1)}
)
assert factored_expansion == derivative

print("c =", c)
print("Expected k(s) = (1/4)*s^3 - (1/2)*s^2 + (1/4)*s")
print("Verified factorization: k(s) = (1/4)*s*(s - 1)^2")
print("Exact derivative coefficients:", sorted(derivative.items()))
print("Submitted coefficients:", sorted(submitted.items()))
print("At s = 1, expected =", evaluate(derivative, F(1)))
print("At s = 1, submitted =", evaluate(submitted, F(1)))
print("CHECK PASS" if derivative == submitted else "CHECK FAIL")
