}

facts = {
    "The capital of Gambia is Banjul.": True,
    "The capital of Nepal is Pokhara.": False,
    "The capital of Gambia is Libreville.": False,
    "The capital of Canada is Toronto.": False,
    "The capital of Iran is Tehran.": True,
    "The capital of Afghanistan is Kabul.": True,
    "The capital of Malaysia is Kuala Lumpur.": True,
    "The capital of Turkey is Istanbul.": False,
    "The capital of the Nigeria is Abuja.": True,
}


def normalize(text):
    for fact, value in facts.items():
        text = text.replace(fact, str(value))
    return (
        text.replace("is less than or equal to", "<=")
        .replace("is greater than", ">")
    )


def evaluate(node):
    """Interpret the expression directly, with exact rational arithmetic."""
    if isinstance(node, ast.Expression):
        return evaluate(node.body)
    if isinstance(node, ast.Constant):
        if type(node.value) is bool:
            return node.value
        if type(node.value) is int:
            return Fraction(node.value)
        raise ValueError("Unexpected literal")
    if isinstance(node, ast.UnaryOp):
        value = evaluate(node.operand)
        if isinstance(node.op, ast.Not):
            return not value
        if isinstance(node.op, ast.USub):
            return -value
        if isinstance(node.op, ast.UAdd):
            return value
    if isinstance(node, ast.BoolOp):
        # Evaluate all operands, not merely the short-circuiting ones.
        values = [evaluate(child) for child in node.values]
        if not all(type(value) is bool for value in values):
            raise ValueError("Non-Boolean logical operand")
        if isinstance(node.op, ast.And):
            return all(values)
        if isinstance(node.op, ast.Or):
            return any(values)
    if isinstance(node, ast.BinOp):
        left, right = evaluate(node.left), evaluate(node.right)
        if isinstance(node.op, ast.Add):
            return left + right
        if isinstance(node.op, ast.Sub):
            return left - right
        if isinstance(node.op, ast.Mult):
            return left * right
        if isinstance(node.op, ast.Div):
            return left / right
    if isinstance(node, ast.Compare):
        left = evaluate(node.left)
        results = []
        for op, child in zip(node.ops, node.comparators):
            right = evaluate(child)
            if isinstance(op, ast.Gt):
                results.append(left > right)
            elif isinstance(op, ast.LtE):
                results.append(left <= right)
            else:
                raise ValueError("Unexpected comparison")
            left = right
        return all(results)
    if isinstance(node, ast.Call):
        if (
            isinstance(node.func, ast.Name)
            and node.func.id in ("max", "min")
            and not node.keywords
        ):
            values = [evaluate(arg) for arg in node.args]
            return (max if node.func.id == "max" else min)(values)
    raise ValueError("Unsupported syntax: " + ast.dump(node))


def main():
    results = {}
    try:
        for label, expression in expressions.items():
            tree = ast.parse(normalize(expression), mode="eval")
            result = evaluate(tree)
            if type(result) is not bool:
                raise ValueError("Option did not evaluate to a Boolean")
            results[label] = result
    except (SyntaxError, ValueError, ZeroDivisionError) as exc:
        print("UNSUPPORTED:", exc)
        print("CHECK UNKNOWN")
        return

    for label, result in results.items():
        print(f"{label} = {result}")

    true_options = [label for label, result in results.items() if result]
    print("True options:", ", ".join(true_options) or "none")

    if len(true_options) != 1:
        print("CHECK FAIL: the question's unique-true premise is false.")
        return

    print("Expected answer:", true_options[0])
    # The submitted response names no option and supplies no equivalent
    # identifying expression. Its generic description is not a selection.
    print("CHECK FAIL: submitted answer does not identify the true option.")


main()
