def value(a=0, b=0):
    return F(a), F(b)

def add(u, v):
    return u[0] + v[0], u[1] + v[1]

def neg(u):
    return -u[0], -u[1]

def sub(u, v):
    return add(u, neg(v))

def mul(u, v):
    a, b = u
    c, d = v
    return a*c + RAD*b*d, a*d + b*c

def div(u, v):
    c, d = v
    norm = c*c - RAD*d*d
    if not norm:
        raise ArithmeticError("Zero denominator")
    return mul(u, (c / norm, -d / norm))

def sign(u):
    a, b = u
    if not b:
        return (a > 0) - (a < 0)
    if not a:
        return (b > 0) - (b < 0)
    if (a > 0) == (b > 0):
        return 1 if a > 0 else -1
    comparison = a*a - RAD*b*b
    if not comparison:
        return 0
    return ((a > 0) - (a < 0)) if comparison > 0 else ((b > 0) - (b < 0))

def text(u):
    a, b = u
    if not b:
        return str(a)
    radical = "sqrt(%d)" % RAD
    magnitude = abs(b)
    term = radical if magnitude == 1 else str(magnitude) + "*" + radical
    if not a:
        return ("-" if b < 0 else "") + term
    return str(a) + (" + " if b > 0 else " - ") + term

