    # Boundary points have xyz=0. At an interior stationary point,
    # Lagrange multiplier equations force two variables to coincide.
    # Setting x=y=a gives 3a^2-18a+14=0.
    discriminant = 18**2 - 4*3*14
    assert discriminant == 4*RAD
    roots = [value(3, F(-1, 3)), value(3, F(1, 3))]
    feasible = []
    rejected = []

