    return add(u, neg(v))

def mul(u, v):
    return (u[0]*v[0] + 39*u[1]*v[1],
            u[0]*v[1] + u[1]*v[0])

def div(u, v):
    d = v[0]*v[0] - 39*v[1]*v[1]
    assert d != 0
    w = mul(u, (v[0], -v[1]))
    return (w[0]/d, w[1]/d)

def const(n):
    return (F(n), F(0))

def scale(u, n):
    return mul(u, const(n))

def square(u):
    return mul(u, u)

def sign(u):
    a, b = u
    if b == 0:
        return (a > 0) - (a < 0)
    if a == 0:
        return (b > 0) - (b < 0)
    if a > 0 and b > 0:
        return 1
    if a < 0 and b < 0:
        return -1
    d = a*a - 39*b*b
    assert d != 0  # sqrt(39) is irrational
    return ((d > 0) - (d < 0)) * ((a > 0) - (a < 0))

def fmt(u):
    a, b = u
    if b == 0:
        return str(a)
    return f"({a}) + ({b})*sqrt(39)"

assert isqrt(39)**2 != 39

