from itertools import product

# C = inadequate clothing in cold weather.
# R = an underlying etiological factor (strain, infection, or injury).
# Y = arthritis.
#
# Enumerate every deterministic binary disease mechanism Y = f(C, R).
# The causal claim being tested is that changing C from 0 to 1 can
# cause arthritis while holding the underlying factors fixed.
tables = list(product((0, 1), repeat=4))

def outcome(table, cold_exposure, root_factor):
    return table[2 * cold_exposure + root_factor]

def cold_can_cause_arthritis(table):
    return any(
        outcome(table, 0, r) == 0 and outcome(table, 1, r) == 1
        for r in (0, 1)
    )

def exposed_person_without_arthritis(table):
    # A and C supply counterexamples to sufficiency, not to causation.
    return any(outcome(table, 1, r) == 0 for r in (0, 1))

def underlying_causes_not_cold(table):
    # B explicitly identifies the root causes, distinguishing them from
    # cold exposure that can trigger an attack of existing arthritis.
    # R aggregates the stated root causes; cold does not change disease
    # presence at a fixed R.
    return all(
        outcome(table, c, r) == r
        for c in (0, 1)
        for r in (0, 1)
    )

def unexposed_person_with_arthritis(table):
    # D supplies counterexamples to necessity, not to causation.
    return any(outcome(table, 0, r) == 1 for r in (0, 1))

constraints = {
    "A": exposed_person_without_arthritis,
    "B": underlying_causes_not_cold,
    "C": exposed_person_without_arthritis,
    "D": unexposed_person_with_arthritis,
}

results = {}
print("Exact enumeration of all 16 binary causal mechanisms:")
for letter, predicate in constraints.items():
    compatible = [t for t in tables if predicate(t)]
    causal = [t for t in compatible if cold_can_cause_arthritis(t)]
    results[letter] = (compatible, causal)
    print(
        f"{letter}: compatible mechanisms={len(compatible)}, "
        f"mechanisms retaining cold as a possible cause={len(causal)}"
    )

decisive = [
    letter for letter, (compatible, causal) in results.items()
    if compatible and not causal
]

submitted = "D"
if decisive == ["B"]:
    print("Expected answer: B")
    print("Submitted answer:", submitted)
    print(
        "B directly distinguishes the root cause from a trigger. "
        "D only shows that inadequate clothing is not necessary."
    )
    # Give an explicit countermodel to D's supposed refutation.
    witness = (0, 1, 1, 1)  # Y = C OR R
    assert constraints["D"](witness)
    assert cold_can_cause_arthritis(witness)
    print(
        "Countermodel for D: Y = C OR R. A warmly dressed person can "
        "have arthritis because R=1, while cold exposure can still "
        "cause arthritis when R=0."
    )
    print("CHECK PASS" if submitted == "B" else "CHECK FAIL")
else:
    print("UNSUPPORTED")
    print("CHECK UNKNOWN")
