    expression = expression.strip()
    for statement, value in facts.items():
        expression = expression.replace(statement, str(value))
    expression = expression.replace("is less than or equal to", "<=")
    expression = expression.replace("is greater than", ">")
    tree = ExactDivision().visit(ast.parse(expression, mode="eval"))
    ast.fix_missing_locations(tree)
    return eval(
        compile(tree, "<given-expression>", "eval"),
        {"__builtins__": {}, "Fraction": Fraction, "max": max, "min": min},
