import itertools
import json

# Each object has two predicates, P and Q.
# Original: some P are not Q -> not all Q are P.
# A, C and D reverse P and Q in the same way.
# B: some P are not Q -> not all P are Q.

forms = {
    "original": ("P", "Q"),
    "A": ("P", "Q"),
    "B": ("P", "P"),
    "C": ("P", "Q"),
    "D": ("P", "Q"),
}

results = {}
for label, (_, conclusion_subject) in forms.items():
    counterexamples = []
    premise_models = 0

    # Two objects suffice: these formulas depend only on whether
    # P-and-not-Q and Q-and-not-P objects exist.
    for model in itertools.product(
        itertools.product((False, True), repeat=2), repeat=2
    ):
        premise = any(p and not q for p, q in model)
        conclusion = (
            any(q and not p for p, q in model)
            if conclusion_subject == "Q"
            else any(p and not q for p, q in model)
        )
        if premise:
            premise_models += 1
            if not conclusion:
                counterexamples.append(model)

    results[label] = {
        "valid": not counterexamples,
        "premise_models": premise_models,
        "countermodels": len(counterexamples),
    }

# Identify the option that does not follow the reasoning pattern
# of the original argument.
different = [
    label for label in "ABCD"
    if results[label]["valid"] != results["original"]["valid"]
]

print(json.dumps({
    "final_answer": different[0] if len(different) == 1 else "UNSUPPORTED",
    "evidence": {
        "criterion": "different logical validity from the given inference",
        "computed": results,
        "explanation": (
            "The original, A, C and D use invalid reversed negation; "
            "B restates its premise equivalently."
        ),
    },
}, separators=(",", ":")))
